SELECT p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icustay_id, i.intime, i.outtime, i.los, s.stay_length, s.in_icu_days, s.out_icu_days, s.total_days, s.mortality_rate, percentile_cont(0.25) within GROUP (ORDER BY v.vital_instability_index) AS q25, percentile_cont(0.50) within GROUP (ORDER BY v.vital_instability_index) AS q50, percentile_cont(0.75) within GROUP (ORDER BY v.vital_instability_index) AS q75, percentile_cont(0.90) within GROUP (ORDER BY v.vital_instability_index) AS q90, (percentile_cont(0.75) within GROUP (ORDER BY v.vital_instability_index) - percentile_cont(0.25) within GROUP (ORDER BY v.vital_instability_index)) / (percentile_cont(0.90) within GROUP (ORDER BY v.vital_instability_index) - percentile_cont(0.10) within GROUP (ORDER BY v.vital_instability_index)) AS interquartile_range FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN stay s ON s.stay_id = i.stay_id JOIN chartevents c ON c.subject_id = p.subject_id AND c.hadm_id = i.hadm_id AND c.charttime BETWEEN i.intime AND i.outtime JOIN vital_signs v ON v.subject_id = p.subject_id AND v.hadm_id = i.hadm_id AND v.charttime BETWEEN i.intime AND i.outtime WHERE p.gender = 'F' AND p.anchor_age BETWEEN 58 AND 68 AND p.anchor_year_group = 'RRT' AND c.itemid IN (SELECT itemid FROM d_items WHERE category = 'Vital Signs') AND v.vital_instability_index < 65 AND c.heart_rate > 100 AND c.charttime <= i.intime + interval '72 hours' GROUP BY p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icustay_id, i.intime, i.outtime, i.los, s.stay_length, s.in_icu_days, s.out_icu_days, s.total_days, s.mortality_rate ORDER BY q25 NULLS LAST, q50 NULLS LAST, q75 NULLS LAST, q90 NULLS LAST;